  async function nextEmployeeNo(){const prefix=(state.settings?.employee_prefix||'EMP').toUpperCase();let max=0;state.employees.forEach(e=>{const m=String(e.employee_number||'').match(new RegExp(`^${prefix}-(\\d+)$`));if(m)max=Math.max(max,+m[1])});return `${prefix}-${String(max+1).padStart(4,'0')}`}
  async function nextRunNo(){
    /* Read the current business's pay-run numbers directly from Supabase so a
       stale in-memory run list can never generate a duplicate number. */
    const res=await client().from('payroll_pay_runs').select('pay_run_number').eq('business_id',state.businessId);
    if(res.error)throw new Error(`Could not determine the next pay run number: ${res.error.message}`);
    const existing=(res.data||[]).map(r=>String(r.pay_run_number||'').trim()).filter(Boolean);
    let prefix='PAY-',width=4,max=0;
    for(const value of existing){
      const m=value.match(/^(.*?)(\d+)$/);
      if(!m)continue;
      const n=Number(m[2]);
      if(!Number.isFinite(n))continue;
      if(n>=max){max=n;prefix=m[1]||'PAY-';width=Math.max(4,m[2].length)}
    }
    let candidate=`${prefix}${String(max+1).padStart(width,'0')}`;
    while(existing.includes(candidate)){
      max+=1;
      candidate=`${prefix}${String(max+1).padStart(width,'0')}`;
    }
    return candidate;
  }
