  function renderEmployeeSuggestions(){for(const [listId,key] of [['peJobTitleOptions','job_title'],['peDepartmentOptions','department'],['peManagerOptions','manager_name']]){const list=$(listId);if(!list)continue;const seen=new Set(),values=state.employees.map(employee=>String(employee[key]||'').trim()).filter(value=>{const normalized=value.toLocaleLowerCase();if(!value||seen.has(normalized))return false;seen.add(normalized);return true}).sort((a,b)=>a.localeCompare(b));list.replaceChildren(...values.map(value=>{const option=document.createElement('option');option.value=value;return option}))}}
  function resetEmployeeForm(){paygEffectiveDateEdited=false;['payrollEmployeeId','peFirst','peMiddle','peLast','pePreferred','peDob','peEmail','peMobile','pePhone','peAddress','peEmergencyName','peEmergencyPhone','peNotes','peJobTitle','peEnd','peDepartment','peManager','peIrd','peBankName','peBankNumber','peBankReference'].forEach(id=>{if($(id))$(id).value=''});$('peStart').value=today();$('peEmploymentType').value='casual';$('peHours').value=state.settings?.default_weekly_hours||40;$('peDays').value=state.settings?.default_working_days||5;$('peFrequency').value=state.settings?.default_pay_frequency||'fortnightly';$('peStatus').value='active';$('pePayType').value='hourly';$('peHourlyRate').value='';$('peSalary').value='';$('peOvertime').value='1.5';$('peHolidayMethod').value='standard';$('peHolidayRate').value=String(ruleNum('holidays','payg_minimum_rate',today()));populateTaxCodeOptions();resetPaygEvidenceForm();$('peStudentLoan').checked=false;$('peKiwiStatus').value='not_enrolled';$('peKiwiEmployee').value=String(ruleNum('kiwisaver','default_employee_rate',today()));$('peKiwiEmployer').value=String(ruleNum('kiwisaver','default_employer_rate',today()));renderEmployeeDocs(null);renderLeaveFields(null);if($('peLeaveHistory'))$('peLeaveHistory').innerHTML='<p class="hint">Save the employee to record leave.</p>';if($('pePayrollHistory'))$('pePayrollHistory').innerHTML='<p class="hint">No payroll history yet.</p>'}
