  async function deleteTimesheet(id){const t=state.timesheets.find(x=>x.id===id);if(!t)return;if(!confirm('Permanently delete this timesheet entry and its attached employee expenses?'))return;const {error}=await client().from('payroll_timesheets').delete().eq('id',id);if(error)return toast(error.message);await audit('timesheet',id,'deleted',t,null);close('payrollTimesheetModal');await load();toast('Timesheet deleted.')}
  function renderTimesheets(){if(!$('payrollTimesheetRows'))return;populateTimesheetSelectors();if(!$('payrollTimesheetFrom').value){$('payrollTimesheetFrom').value=addDays(today(),-14);$('payrollTimesheetTo').value=today()}const from=$('payrollTimesheetFrom').value,to=$('payrollTimesheetTo').value,emp=$('payrollTimesheetEmployee').value,status=$('payrollTimesheetStatus').value;const em=new Map(state.employees.map(e=>[e.id,displayName(e)])),jm=new Map(state.jobs.map(j=>[j.id,j.costing_number+' · '+(j.job_description||j.customer_name||'Job')]));const arr=state.timesheets.filter(t=>(!from||t.work_date>=from)&&(!to||t.work_date<=to)&&(!emp||t.employee_id===emp)&&(!status||t.status===status));$('payrollTimesheetRows').innerHTML=arr.map(t=>`<tr><td>${t.status==='submitted'?`<input type="checkbox" data-ts-select="${t.id}">`:''}</td><td>${iso(t.work_date)}</td><td>${esc(em.get(t.employee_id)||'Employee')}</td><td>${esc(jm.get(t.job_costing_id)||'—')}</td><td><strong>${num(t.total_hours).toFixed(2)}</strong>${state.timesheetExpenses.some(x=>x.timesheet_id===t.id)?`<small>Expenses ${money(state.timesheetExpenses.filter(x=>x.timesheet_id===t.id).reduce((a,x)=>a+num(x.amount),0))}</small>`:''}</td><td><span class="badge payroll-status ${t.status}">${esc(human(t.status))}</span></td><td><div class="row-actions"><button class="secondary" data-ts-edit="${t.id}">View / Edit</button>${t.status==='submitted'?`<button class="primary" data-ts-approve="${t.id}">Approve</button>`:''}<button class="danger" data-ts-delete="${t.id}">Delete</button></div></td></tr>`).join('')||'<tr><td colspan="7">No timesheets for this period.</td></tr>';$('payrollTimesheetCards').innerHTML=arr.map(t=>`<div class="payroll-mobile-card"><strong>${esc(em.get(t.employee_id)||'Employee')}</strong><span>${iso(t.work_date)} · ${num(t.total_hours).toFixed(2)} hours</span><small>${esc(jm.get(t.job_costing_id)||'No job')}${state.timesheetExpenses.some(x=>x.timesheet_id===t.id)?' · Expenses '+money(state.timesheetExpenses.filter(x=>x.timesheet_id===t.id).reduce((a,x)=>a+num(x.amount),0)):''}</small><span class="badge payroll-status ${t.status}">${esc(human(t.status))}</span><button class="secondary" data-ts-edit="${t.id}">View</button>${t.status==='submitted'?`<button class="primary" data-ts-approve="${t.id}">Approve</button>`:''}</div>`).join('');document.querySelectorAll('[data-ts-edit]').forEach(b=>b.onclick=()=>openTimesheet(state.timesheets.find(t=>t.id===b.dataset.tsEdit)));document.querySelectorAll('[data-ts-approve]').forEach(b=>b.onclick=()=>approveTimesheets([b.dataset.tsApprove]));document.querySelectorAll('[data-ts-delete]').forEach(b=>b.onclick=()=>deleteTimesheet(b.dataset.tsDelete))}
  async function approveTimesheets(ids){if(!ids.length)return toast('Select submitted timesheets first.');const now=new Date().toISOString();const {error}=await client().from('payroll_timesheets').update({status:'approved',approved_at:now,approved_by:window.SAAS.state.user.id,updated_at:now,updated_by:window.SAAS.state.user.id}).in('id',ids).eq('status','submitted');if(error)return toast(error.message);for(const id of ids)await audit('timesheet',id,'approved',null,{status:'approved'});await load();toast(`${ids.length} timesheet${ids.length===1?'':'s'} approved`)}

  // Country rules are effective-dated in Supabase. Finalised runs snapshot the exact rules used.
  function rule(type,key,date=today()){return state.countryRules.find(r=>r.rule_type===type&&r.rule_key===key&&r.effective_from<=date&&(!r.effective_to||r.effective_to>=date))||null}
  function requiredRule(type,key,date=today()){const r=rule(type,key,date);if(!r)throw new Error(`Payroll tax rule missing for ${String(state.settings?.country_code||'').toUpperCase()}: ${type}.${key} on ${date}. Ask the Super Admin to configure Country Payroll Tax Rules.`);return r}
  function ruleNum(type,key,date,fallback=null){const r=rule(type,key,date);if(r?.numeric_value!=null)return num(r.numeric_value);if(fallback!==null)return num(fallback);throw new Error(`Payroll tax rule ${type}.${key} has no numeric value for ${date}.`)}
  function ruleJson(type,key,date,fallback=null){const r=rule(type,key,date);if(r?.json_value!=null)return r.json_value;if(fallback!==null)return fallback;throw new Error(`Payroll tax rule ${type}.${key} has no JSON value for ${date}.`)}
  function activeRuleSnapshot(date){return state.countryRules.filter(r=>r.effective_from<=date&&(!r.effective_to||r.effective_to>=date)).map(r=>({type:r.rule_type,key:r.rule_key,numeric_value:r.numeric_value,text_value:r.text_value,json_value:r.json_value,effective_from:r.effective_from,effective_to:r.effective_to,source_note:r.source_note}))}
  function ruleText(type,key,date=today()){const r=requiredRule(type,key,date);if(r?.text_value!=null&&String(r.text_value).trim())return String(r.text_value);throw new Error(`Payroll tax rule ${type}.${key} has no text value for ${date}.`)}
  function annualHolidayRules(date){return{owp_formula_divisor_weeks:ruleNum('holidays','owp_formula_divisor_weeks',date),awe_standard_divisor_weeks:ruleNum('holidays','awe_standard_divisor_weeks',date),awe_lookback_months:ruleNum('holidays','awe_lookback_months',date),annual_holiday_payment_selection:ruleText('holidays','annual_holiday_payment_selection',date)}}
  function statutoryLeaveRules(date){const rows=state.countryRules.filter(r=>r.rule_type==='statutory_leave'&&r.effective_from<=date&&(!r.effective_to||r.effective_to>=date));const out={};for(const r of rows)out[r.rule_key]=r.numeric_value!=null?num(r.numeric_value):r.text_value!=null?r.text_value:r.json_value;return out}
  function calculateStatutoryLeave(input){if(!window.FinloNZStatutoryLeave?.calculateStatutoryLeave)throw new Error('NZ statutory leave engine is unavailable.');return window.FinloNZStatutoryLeave.calculateStatutoryLeave({...input,rules:input.rules||statutoryLeaveRules(input.date||today())})}
