  function calculateAnnualHoliday(input){if(!window.FinloNZHolidays?.calculate)throw new Error('NZ annual-holiday calculation engine is unavailable.');const relevantDate=input?.holidayStart||today();return window.FinloNZHolidays.calculate({...input,rules:annualHolidayRules(relevantDate)})}
  async function saveAnnualHolidayCalculation(input){const result=calculateAnnualHoliday(input),employeeId=input?.employeeId;if(!employeeId)throw new Error('Employee is required for an annual-holiday calculation.');if(!window.FinloNZHolidays?.buildStoragePayload)throw new Error('NZ annual-holiday storage builder is unavailable.');const payload=window.FinloNZHolidays.buildStoragePayload(result,input,{businessId:state.businessId,employeeId,leaveTypeId:input.leaveTypeId,payRunId:input.payRunId,leaveTransactionId:input.leaveTransactionId,rulesSnapshot:{country:state.settings?.country_code||'NZ',rules:activeRuleSnapshot(input.holidayStart)}});const {data,error}=await client().from('payroll_statutory_leave_calculations').insert(payload).select().single();if(error)throw error;return{record:data,result}}
  function annualIncomeTax(a,date){a=Math.max(0,a);const brackets=ruleJson('paye','annual_brackets',date);let tax=0,lower=0;for(const b of brackets){const upper=b.max==null?a:Math.min(a,num(b.max));if(upper>lower)tax+=(upper-lower)*num(b.rate);if(b.max==null||a<=num(b.max))break;lower=num(b.max)}return tax}
  function ietc(a,date){const r=ruleJson('paye','ietc',date);if(a<num(r.min_income)||a>=num(r.max_income))return 0;if(a<=num(r.full_to))return num(r.credit);return Math.max(0,num(r.credit)-(a-num(r.full_to))*num(r.abatement))}
