    if(det.status==='ineligible')return{status:'not_eligible',route:det.route||null,reasons:[{code:'payg_not_eligible',message:'PAYG annual holiday pay is not applicable under the current eligibility determination.'}]};
    if(det.status!=='eligible')return{status:'needs_confirmation',route:det.route||null,reasons:[{code:'payg_eligibility_not_confirmed',message:'PAYG holiday pay needs confirmation before this employee\'s pay can be finalised.'}]};
    const minimumRateRule=rule('holidays','payg_minimum_rate',run.pay_date);if(!minimumRateRule)return{status:'needs_confirmation',reasons:[{code:'payg_minimum_rule_required',message:'Effective PAYG minimum rule is required.'}]};
