    const td=p6NeedsConfirmation?{paye:null,student:null}:(p7.status==='calculated'?{paye:num(p7.paye),student:num(p7.studentLoan)}:(p7NeedsConfirmation?{paye:null,student:null}:(p7NZ?{paye:0,student:0}:payeFor(x.employee,taxableBase,run.pay_frequency,run.pay_date))));
