    const employerGross=unresolved?null:(p7.status==='calculated'?num(p7.kiwisaverEmployerGross):(p7NZ?0:(x.employee.kiwisaver_status==='enrolled'?trunc2(taxableBase*num(x.employee.kiwisaver_employer_rate)/100):0)));
