  async function savePayrollSettings(){
    if(!state.businessId||!state.settings)return toast('Payroll settings are not ready to save.');
    const button=$('payrollSaveSettings');button.disabled=true;$('payrollSettingsStatus').textContent='Saving…';
    try{
      const payload={business_id:state.businessId,country_code:$('payrollSettingCountry').value,currency:appSettings().currency||currency(),default_pay_frequency:$('payrollSettingFrequency').value,default_pay_day:num($('payrollSettingPayDay').value),week_start_day:num($('payrollSettingWeekStart').value),default_weekly_hours:num($('payrollSettingHours').value),default_working_days:num($('payrollSettingDays').value),employee_prefix:$('payrollSettingPrefix').value.trim().toUpperCase()||'EMP',payslip_note:$('payrollSettingPayslipNote').value.trim()||null,updated_at:new Date().toISOString(),updated_by:window.SAAS.state.user.id};
      let result=await client().from('payroll_settings').upsert(payload,{onConflict:'business_id'});if(result.error)throw result.error;
      const stamp=new Date().toISOString(),payItemRows=state.payItems.map(i=>({id:i.id,business_id:state.businessId,item_type:document.querySelector(`[data-pi-type="${i.id}"]`).value,name:document.querySelector(`[data-pi-name="${i.id}"]`).value.trim(),calculation_type:document.querySelector(`[data-pi-calc="${i.id}"]`).value,default_rate:num(document.querySelector(`[data-pi-rate="${i.id}"]`).value),taxable:document.querySelector(`[data-pi-type="${i.id}"]`).value==='reimbursement'?false:!document.querySelector(`[data-pi-taxfree="${i.id}"]`).checked,statutory_earning_code:document.querySelector(`[data-pi-statutory="${i.id}"]`).value||null,holidays_gross_earnings_mode:document.querySelector(`[data-pi-gross-mode="${i.id}"]`).value||'needs_confirmation',owp_inclusion_mode:document.querySelector(`[data-pi-owp-mode="${i.id}"]`).value||'needs_confirmation',rdp_inclusion_mode:document.querySelector(`[data-pi-rdp-mode="${i.id}"]`)?.value||'needs_confirmation',adp_inclusion_mode:document.querySelector(`[data-pi-adp-mode="${i.id}"]`)?.value||'needs_confirmation',updated_at:stamp}));
      if(payItemRows.length){result=await client().from('payroll_pay_items').upsert(payItemRows,{onConflict:'id'});if(result.error)throw result.error}
      const leaveTypeRows=state.leaveTypes.map(l=>({id:l.id,business_id:state.businessId,name:document.querySelector(`[data-lt-name="${l.id}"]`).value.trim(),paid:document.querySelector(`[data-lt-paid="${l.id}"]`).checked}));
      if(leaveTypeRows.length){result=await client().from('payroll_leave_types').upsert(leaveTypeRows,{onConflict:'id'});if(result.error)throw result.error}
      const docTypeRows=state.docTypes.map(d=>({id:d.id,business_id:state.businessId,name:document.querySelector(`[data-dt-name="${d.id}"]`).value.trim(),required:document.querySelector(`[data-dt-required="${d.id}"]`).checked}));
      if(docTypeRows.length){result=await client().from('payroll_document_types').upsert(docTypeRows,{onConflict:'id'});if(result.error)throw result.error}
      state.settingsDirty=false;$('payrollSettingsStatus').textContent='Saved';await load();toast('Payroll settings saved');
    }catch(err){state.settingsDirty=true;$('payrollSettingsStatus').textContent='Save incomplete';toast(`Could not save all payroll settings: ${err?.message||err}. Some earlier changes may have saved; check and try again.`)}finally{button.disabled=false}
  }
  async function addPayItem(){if(!payrollSettingsCanDiscard())return;const name=prompt('Pay item name:');if(!name)return;const type=prompt('Type: earning, allowance, reimbursement, deduction or contribution','allowance');if(!['earning','allowance','reimbursement','deduction','contribution'].includes(type))return toast('Invalid pay item type.');const {error}=await client().from('payroll_pay_items').insert({business_id:state.businessId,item_type:type,name,calculation_type:'fixed',default_rate:0,taxable:type!=='reimbursement',statutory_earning_code:type==='reimbursement'?'reimbursement':null,holidays_gross_earnings_mode:'needs_confirmation',owp_inclusion_mode:'needs_confirmation',rdp_inclusion_mode:'needs_confirmation',adp_inclusion_mode:'needs_confirmation'});if(error)return toast(error.message);state.settingsDirty=false;await load()}
  async function addLeaveType(){if(!payrollSettingsCanDiscard())return;const name=prompt('Leave type name:');if(!name)return;const {error}=await client().from('payroll_leave_types').insert({business_id:state.businessId,name:name.trim(),paid:true});if(error)return toast(error.message);state.settingsDirty=false;await load()}
  async function addDocType(){if(!payrollSettingsCanDiscard())return;const name=prompt('Document type name:');if(!name)return;const {error}=await client().from('payroll_document_types').insert({business_id:state.businessId,name,required:false});if(error)return toast(error.message);state.settingsDirty=false;await load()}

  function renderReportSelectors(){if(!$('payrollReportEmployee'))return;$('payrollReportEmployee').innerHTML='<option value="">All employees</option>'+state.employees.map(e=>`<option value="${e.id}">${esc(displayName(e))}</option>`).join('');$('payrollReportJob').innerHTML='<option value="">All jobs</option>'+state.jobs.map(j=>`<option value="${j.id}">${esc(j.costing_number+' · '+(j.job_description||j.customer_name||'Job'))}</option>`).join('');if(!$('payrollReportFrom').value){$('payrollReportFrom').value=startOfMonth();$('payrollReportTo').value=today()}}
  function renderPayrollReport(){if(!$('payrollReportRows'))return;const from=$('payrollReportFrom')?.value||'',to=$('payrollReportTo')?.value||'',emp=$('payrollReportEmployee')?.value||'',job=$('payrollReportJob')?.value||'',finalRuns=state.runs.filter(r=>r.status==='finalised'&&(!from||r.pay_date>=from)&&(!to||r.pay_date<=to)),runIds=new Set(finalRuns.map(r=>r.id));let rows=state.runEmployees.filter(x=>runIds.has(x.pay_run_id)&&(!emp||x.employee_id===emp));if(job){const linked=new Set(state.runLines.filter(l=>l.job_costing_id===job).map(l=>l.pay_run_employee_id));rows=rows.filter(x=>linked.has(x.id))}state.reportRows=rows;const sums=rows.reduce((z,x)=>({gross:z.gross+num(x.gross_pay),paye:z.paye+num(x.paye),net:z.net+num(x.net_pay),emp:z.emp+num(x.kiwisaver_employer_gross),reimb:z.reimb+num(x.reimbursements),cost:z.cost+num(x.total_employment_cost)}),{gross:0,paye:0,net:0,emp:0,reimb:0,cost:0});$('payrollReportGross').textContent=money(sums.gross);$('payrollReportPaye').textContent=money(sums.paye);$('payrollReportNet').textContent=money(sums.net);$('payrollReportEmployer').textContent=money(sums.emp);$('payrollReportReimbursements').textContent=money(sums.reimb);$('payrollReportCost').textContent=money(sums.cost);const groups={};rows.forEach(x=>{const e=state.employees.find(e=>e.id===x.employee_id),n=e?displayName(e):(x.employee_snapshot?.name||'Employee'),g=groups[n]||(groups[n]={gross:0,paye:0,kiwi:0,net:0,cost:0});g.gross+=num(x.gross_pay);g.paye+=num(x.paye);g.kiwi+=num(x.kiwisaver_employee);g.net+=num(x.net_pay);g.cost+=num(x.total_employment_cost)});$('payrollReportRows').innerHTML=Object.entries(groups).map(([n,g])=>`<tr><td>${esc(n)}</td><td>${money(g.gross)}</td><td>${money(g.paye)}</td><td>${money(g.kiwi)}</td><td>${money(g.net)}</td><td>${money(g.cost)}</td></tr>`).join('')||'<tr><td colspan="6">No finalised payroll in this period.</td></tr>'}
  function reportCsv(){const rows=[['Employee','Gross','PAYE','KiwiSaver Employee','Student Loan','Net','Employer Contributions','Total Employment Cost']];state.reportRows.forEach(x=>{const e=state.employees.find(e=>e.id===x.employee_id);rows.push([e?displayName(e):(x.employee_snapshot?.name||'Employee'),x.gross_pay,x.paye,x.kiwisaver_employee,x.student_loan,x.net_pay,x.kiwisaver_employer_gross,x.total_employment_cost])});window.FinloCore.csv.downloadCsvRows(`payroll-report-${$('payrollReportFrom').value}-to-${$('payrollReportTo').value}.csv`,rows,{newline:'\n',revokeDelay:0})}
